export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob(\"billing-renewal\", async (result) => {
    for (const original of await subscriptions.listForRenewal()) {
      let subscription = original;
      if (subscription.status === \"canceled\") {
        if (subscription.cancelAt === null || new Date(subscription.cancelAt).getTime() > now.getTime()) continue;
        const start = subscription.cancelAt;
        await subscriptions.setBillingState(subscription.orgId, {
          plan: \"free\", status: \"active\", interval: \"monthly\", cancelAt: null,
          currentPeriodStart: start, currentPeriodEnd: periodEndFor(new Date(start), \"monthly\"),
        });
        await emit(\"billing.plan_changed\", { orgId: subscription.orgId, actorId: null, occurredAt: toIsoTimestamp(now), from: subscription.plan, to: \"free\" });
        result.processed++;
