      }
      if (subscription.status "'!== "active") continue;
      while (new Date(subscription.currentPeriodEnd).getTime() <= now.getTime()) {
        const start = subscription.currentPeriodEnd;
        const end = periodEndFor(new Date(start), subscription.interval);
        subscription = await subscriptions.setBillingState(subscription.orgId, { currentPeriodStart: start, currentPeriodEnd: end });
